describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 10.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets and overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [
              { upToGrams: 500, costCents: 300 },
              { upToGrams: 1000, costCents: 500 },
            ],
            800,
          ),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 300 },
      { upToGrams: 500, costCents: 200 },
      { upToGrams: 2000, costCents: 500 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for items with zero total weight", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects correct bracket (weight at boundary)", () => {
      // 500g exactly → bracket upToGrams=500, costCents=200
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(200);
    });

    it("selects correct bracket (weight below boundary)", () => {
      // 499g → first sorted bracket ≥ 499 is upToGrams=500, costCents=200
      expect(calc.computeShippingCents([makeLine("a", 499)], 1000)).toBe(200);
    });

    it("selects next bracket when weight exceeds lower boundary", () => {
      // 501g → upToGrams=1000, costCents=300
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(300);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g exactly → bracket upToGrams=2000, costCents=500
      expect(calc.computeShippingCents([makeLine("a", 2000)], 1000)).toBe(500);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      // 2001g → overflow defaults to last bracket cost (500)
      expect(calc.computeShippingCents([makeLine("a", 2001)], 1000)).toBe(500);
    });

    it("uses explicit overflowCostCents when configured", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [{ upToGrams: 500, costCents: 200 }],
        999,
      );
      expect(
        calcWithOverflow.computeShippingCents([makeLine("a", 1000)], 1000),
      ).toBe(999);
    });

    it("multiplies weight by quantity", () => {
      // 2 items of 300g each = 600g → bracket upToGrams=1000, costCents=300
      expect(
        calc.computeShippingCents([makeLine("a", 300, 2)], 1000),
      ).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart", () => {
  describe("add", () => {
    it("adds a product with given quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding the same product twice", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productA, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 0)).toThrow(RangeError);
      expect(() => cart.add(productA, -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      const badProduct: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
      expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes an existing product and returns true", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity of existing product", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity set to 0", () => {
      const cart = new Cart();
      cart.add(productA, 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for non-existent product", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("nonexistent", 1)).toThrow(
        "Product nonexistent is not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(productA, 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("removes all items", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      cart.add(productB, 1);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that does not affect internal state", () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const snap = cart.snapshot();
      (snap as any)[0].quantity = 99;
      expect(cart.itemCount).toBe(2);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents * quantity", () => {
      const cart = new Cart();
      cart.add(productA, 2); // 2000
      cart.add(productB, 1); // 2000
      const totals = cart.totals();
      expect(totals.subtotalCents).toBe(4000);
    });

    it("applies discount to subtotal", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({ discountPolicy: mockDiscount });
      cart.add(productA, 1); // subtotal 1000
      const totals = cart.totals();
      expect(totals.discountCents).toBe(500);
      expect(mockDiscount.computeDiscountCents).toHaveBeenCalledWith(1000);
    });

    it("clamps discount to [0, subtotal]", () => {
      const overDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(9999),
      };
      const cart = new Cart({ discountPolicy: overDiscount });
      cart.add(productA, 1); // subtotal 1000
      expect(cart.totals().discountCents).toBe(1000);
    });

    it("clamps negative discount to 0", () => {
      const negDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ discountPolicy: negDiscount });
      cart.add(productA, 1);
      expect(cart.totals().discountCents).toBe(0);
    });

    it("computes tax on discounted subtotal", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(50),
      };
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        region: "US-CA",
      });
      cart.add(productA, 1); // subtotal 1000, discount 200, discounted = 800
      cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
    });

    it("computes shipping against discounted subtotal and lines", () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(300),
      };
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        shippingCalculator: mockShipping,
      });
      cart.add(productA, 1); // subtotal 1000, discounted 900
      cart.totals();
      expect(mockShipping.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        900,
      );
    });

    it("total = discountedSubtotal + tax + shipping", () => {
      const mockDiscount: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(100),
      };
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(72),
      };
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy: mockDiscount,
        taxCalculator: mockTax,
        shippingCalculator: mockShipping,
      });
      cart.add(productA, 1); // subtotal 1000
      const totals = cart.totals();
      // discounted = 1000 - 100 = 900; total = 900 + 72 + 500 = 1472
      expect(totals.totalCents).toBe(1472);
    });

    it("empty cart produces all zeros", () => {
      const cart = new Cart();
      const totals = cart.totals();
      expect(totals).toEqual({
        subtotalCents: 0,
        discountCents: 0,
        taxCents: 0,
        shippingCents: 0,
        totalCents: 0,
      });
    });

    it("defaults to US region", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(0),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(productA, 1);
      cart.totals();
      expect(mockTax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
    });

    it("clamps negative tax to 0", () => {
      const mockTax: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(-50),
      };
      const cart = new Cart({ taxCalculator: mockTax });
      cart.add(productA, 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const mockShipping: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(-100),
      };
      const cart = new Cart({ shippingCalculator: mockShipping });
      cart.add(productA, 1);
