        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("sum can exceed subtotal (caller clamps)", () => {
      const p1 = new PercentageDiscountPolicy(80); // 800
      const p2 = new FixedAmountDiscountPolicy(500); // capped to 500 in fixed, but sum still applies
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // 80% of 1000 = 800, FixedAmount min(500,1000)=500 → sum = 1300
      expect(composite.computeDiscountCents(1000)).toBe(1300);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy([p1], "sum");
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100 → remaining 900
      const p2 = new PercentageDiscountPolicy(10); // 10% of 900 = 90 → remaining 810
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      const fixed = new FixedAmountDiscountPolicy(500); // takes 500 first → remaining 500
      const percent = new PercentageDiscountPolicy(10); // 10% of 500 = 50
      const composite1 = new CompositeDiscountPolicy([fixed, percent], "chain");
      expect(composite1.computeDiscountCents(1000)).toBe(550);

      // Reverse order: 10% of 1000 = 100 → remaining 900, then min(500,900)=500
      const composite2 = new CompositeDiscountPolicy([percent, fixed], "chain");
      expect(composite2.computeDiscountCents(1000)).toBe(600);
    });

    it("chain cannot exceed original subtotal", () => {
      const p1 = new FixedAmountDiscountPolicy(700);
      const p2 = new FixedAmountDiscountPolicy(700);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      // First takes min(700, 1000) = 700, remaining 300; second takes min(700, 300) = 300
      expect(composite.computeDiscountCents(1000)).toBe(1000);
    });

    it("returns 0 for zero subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const composite = new CompositeDiscountPolicy([p1], "chain");
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });

  describe("defaults to sum mode", () => {
    it("uses sum when mode is not specified", () => {
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(50);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      // sum: 10% of 1000 = 100, fixed min(50,1000)=50 → 150
      expect(composite.computeDiscountCents(1000)).toBe(150);
    });
  });
});
"}

