    expect(result[0].quantity).toBe(2);
    expect(result[1].quantity).toBe(1);
  });

  it("preserves product identity fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
