import { Cart } from "../src/cart.ts";
import { InventoryError, type PriceFetcher, type InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";
import type { Product } from "../src/product.ts";
import { PercentageDiscountPolicy } from "../src/pricing.ts";
import { FlatShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart.checkout()", () => {
  describe("without collaborators", () => {
    it("returns totals and lines snapshot", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.lines).toHaveLength(1);
      expect(result.lines[0].quantity).toBe(2);
    });
  });

  describe("with priceFetcher", () => {
    it("refreshes prices before computing totals", async () => {
      const cart = new Cart();
      cart.add(productA, 1); // originally 1000
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1500),
      };
      const result = await cart.checkout({ priceFetcher: fetcher });
      expect(result.totals.subtotalCents).toBe(1500);
      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    });

    it("propagates fetcher errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher: fetcher })).rejects.toThrow(
        "price service down",
      );
    });
  });

  describe("with inventoryChecker", () => {
    it("passes when all items are available", async () => {
      const cart = new Cart();
      cart.add(productA, 2);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
      };
      const result = await cart.checkout({ inventoryChecker: checker });
      expect(result.totals.subtotalCents).toBe(2000);
      expect(checker.check).toHaveBeenCalledWith("a", 2);
    });

    it("throws InventoryError when item unavailable", async () => {
      const cart = new Cart();
      cart.add(productA, 5);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 2,
          reason: "low stock",
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(5);
        expect(ie.available).toBe(2);
        expect(ie.message).toBe("low stock");
      }
    });

    it("throws InventoryError on partial-stock denial (available < requested)", async () => {
      const cart = new Cart();
      cart.add(productA, 10);
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 3,
        }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(10);
        expect(ie.available).toBe(3);
      }
    });

    it("checks items in order and fails on first denial", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      cart.add(productB, 1);
      const checker: InventoryChecker = {
        check: vi
          .fn()
          .mockResolvedValueOnce({ available: true, availableQuantity: 5 })
          .mockResolvedValueOnce({ available: false }),
      };
      try {
        await cart.checkout({ inventoryChecker: checker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("b");
      }
    });
  });

  describe("with asyncTaxProvider", () => {
    it("uses async tax rate for tax computation", async () => {
      const cart = new Cart();
      cart.add(productA, 1); // subtotal 1000
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // tax = floor(1000 * 0.1) = 100
      expect(result.totals.taxCents).toBe(100);
      expect(provider.getRate).toHaveBeenCalledWith("US");
    });

    it("applies discount before async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(20),
        region: "US",
      });
      cart.add(productA, 1); // subtotal 1000, discount 200, discounted 800
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // tax = floor(800 * 0.1) = 80
      expect(result.totals.taxCents).toBe(80);
      expect(result.totals.discountCents).toBe(200);
    });

    it("includes shipping in total with async tax", async () => {
      const cart = new Cart({
        shippingCalculator: new FlatShippingCalculator(500),
      });
      cart.add(productA, 1); // subtotal 1000
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.05),
      };
      const result = await cart.checkout({ asyncTaxProvider: provider });
      // discounted = 1000, tax = floor(1000 * 0.05) = 50, shipping = 500
      // total = 1000 + 50 + 500 = 1550
      expect(result.totals.shippingCents).toBe(500);
      expect(result.totals.totalCents).toBe(1550);
    });

    it("propagates async tax provider errors", async () => {
      const cart = new Cart();
      cart.add(productA, 1);
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      await expect(cart.checkout({ asyncTaxProvider: provider })).rejects.toThrow(
        "tax service down",
      );
    });
  });

  describe("full pipeline with all collaborators", () => {
    it("refreshes prices, checks inventory, then computes totals with async tax", async () => {
      const cart = new Cart({
        discountPolicy: new PercentageDiscountPolicy(10),
        shippingCalculator: new FlatShippingCalculator(300),
        region: "FR",
      });
      cart.add(productA, 2); // original subtotal 2000

      const fetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockResolvedValue(1200),
      };
      const checker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
      };
      const provider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.2),
      };

      const result = await cart.checkout({
        priceFetcher: fetcher,
        inventoryChecker: checker,
        asyncTaxProvider: provider,
      });

      // refreshed subtotal: 1200 * 2 = 2400
      expect(result.totals.subtotalCents).toBe(2400);
      // discount: 10% of 2400 = 240
      expect(result.totals.discountCents).toBe(240);
      // discounted: 2400 - 240 = 2160
      // tax: floor(2160 * 0.2) = 432
      expect(result.totals.taxCents).toBe(432);
      // shipping: 300 (flat)
      expect(result.totals.shippingCents).toBe(300);
      // total: 2160 + 432 + 300 = 2892
      expect(result.totals.totalCents).toBe(2892);

      expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
      expect(checker.check).toHaveBeenCalledWith("a", 2);
      expect(provider.getRate).toHaveBeenCalledWith("FR");
    });
  });
});
"}

