import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number,
  quantity: number = 1,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 100, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for any lines and subtotal", () => {
    expect(calc.computeShippingCents([makeLine("a", 500)], 5000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
    });

    it("accepts valid parameters", () => {
      expect(() => new FlatShippingCalculator(500, 5000)).not.toThrow();
    });

    it("accepts zero flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat fee for non-empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([makeLine("a", 100)], 1000)).toBe(500);
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(500);
      expect(calc.computeShippingCents([], 1000)).toBe(0);
    });

    it("returns 0 when subtotal meets free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 5000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 6000)).toBe(0);
    });

    it("returns flat fee when subtotal below free-over threshold", () => {
      const calc = new FlatShippingCalculator(500, 5000);
      expect(calc.computeShippingCents([makeLine("a", 100)], 4999)).toBe(500);
    });

    it("works without freeOverCents configured", () => {
      const calc = new FlatShippingCalculator(999);
      expect(calc.computeShippingCents([makeLine("a", 100)], 99999)).toBe(999);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty brackets array", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 100, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 10.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 100, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("accepts valid brackets and overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [
              { upToGrams: 500, costCents: 300 },
              { upToGrams: 1000, costCents: 500 },
            ],
            800,
          ),
      ).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 300 },
      { upToGrams: 500, costCents: 200 },
      { upToGrams: 2000, costCents: 500 },
    ]);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 for items with zero total weight", () => {
      const lines: CartLine[] = [
        { product: { id: "a", name: "A", unitPriceCents: 100 }, quantity: 2 },
      ];
      expect(calc.computeShippingCents(lines, 200)).toBe(0);
    });

    it("selects correct bracket (weight at boundary)", () => {
      // 500g exactly → bracket upToGrams=500, costCents=200
      expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(200);
    });

    it("selects correct bracket (weight below boundary)", () => {
      // 499g → first sorted bracket ≥ 499 is upToGrams=500, costCents=200
      expect(calc.computeShippingCents([makeLine("a", 499)], 1000)).toBe(200);
    });

    it("selects next bracket when weight exceeds lower boundary", () => {
      // 501g → upToGrams=1000, costCents=300
      expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(300);
    });

    it("selects highest bracket at its boundary", () => {
      // 2000g exactly → bracket upToGrams=2000, costCents=500
      expect(calc.computeShippingCents([makeLine("a", 2000)], 1000)).toBe(500);
    });

    it("uses heaviest bracket cost as overflow default", () => {
      // 2001g → overflow defaults to last bracket cost (500)
      expect(calc.computeShippingCents([makeLine("a", 2001)], 1000)).toBe(500);
    });

    it("uses explicit overflowCostCents when configured", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        [{ upToGrams: 500, costCents: 200 }],
        999,
      );
      expect(
        calcWithOverflow.computeShippingCents([makeLine("a", 1000)], 1000),
      ).toBe(999);
    });

    it("multiplies weight by quantity", () => {
      // 2 items of 300g each = 600g → bracket upToGrams=1000, costCents=300
      expect(
        calc.computeShippingCents([makeLine("a", 300, 2)], 1000),
      ).toBe(300);
    });
  });
});

